import{d as s,C as t,o as p,c as h,E as i,a3 as o}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"井卦","description":"第四十八卦·水风井——木上有水，井。井不是「有水」这件事，而是「让水到达人手中」这件事：可汲是条件，供饮是落实，不封闭其养才是大成。","frontmatter":{"title":"井卦","description":"第四十八卦·水风井——木上有水，井。井不是「有水」这件事，而是「让水到达人手中」这件事：可汲是条件，供饮是落实，不封闭其养才是大成。","category":"hexagram","aliases":["井","水风井","井卦"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/48-shuifengjing.md","filePath":"yijing/hexagrams/48-shuifengjing.md","lastUpdated":1792641266000}'),d={name:"yijing/hexagrams/48-shuifengjing.md"},q=s({...d,setup(u){const a=[{id:"jing",term:"井",pinyin:"jǐng",meaning:"水井。卦中既指具体的井，也指「供养之道」。",context:"全卦的关键不在「井里有水」，而在「水如何到达人手中」——彖传以「巽乎水而上水」释之。"},{id:"yi",term:"邑",pinyin:"yì",meaning:"聚落、城邑。",context:"「改邑不改井」：城邑可以迁改，井的所在与供养功能相对固定。"},{id:"jingjing",term:"往来井井",pinyin:"wǎng lái jǐng jǐng",meaning:"往来的人都到井边取水。",context:"写井的常养之性——人来人往，供养的需要始终存在。"},{id:"qi",term:"汔",pinyin:"qì",meaning:"几乎、将近。",context:"「汔至亦未繘井」：汲水几乎到井口了，却终究没有把水取上来——接近完成不等于完成。"},{id:"yu",term:"繘",pinyin:"jú",meaning:"汲水的绳索。此处训释各家有异。",context:"「未繘井」谓未完成汲取之功。彖传「未有功也」即释此句。"},{id:"lei",term:"羸",pinyin:"léi",meaning:"牵累、损伤。",context:"「羸其瓶」：汲水的瓶受损，以致汲水失败——已近成功，却因最后一环失手。"},{id:"qin",term:"禽",pinyin:"qín",meaning:"禽鸟。具体解释有差异，此从禽鸟。",context:"「旧井无禽」：废弃之井，连禽鸟也不来——重点在它已失去吸引取用者的作用。"},{id:"fu",term:"鲋",pinyin:"fù",meaning:"此处常释为井中的小鱼。",context:"「井谷射鲋」训释有差异，此取「水向下流注、只能润及井中小鱼」一路。"},{id:"weng",term:"瓮",pinyin:"wèng",meaning:"汲水的陶器。",context:"「瓮敝漏」：汲水的瓮已破损漏水——器具不能承载，水就到不了使用者手里。"},{id:"xie",term:"渫",pinyin:"xiè",meaning:"清除井中的淤泥。",context:"与「甃」分工不同：渫清淤（九三），甃护壁（六四）。"},{id:"ce",term:"恻",pinyin:"cè",meaning:"惋惜、恻然。",context:"「为我心恻」：井已淘清却无人饮用，因而惋惜。「我」如何理解，注家有讨论，不必直接认定是作者自述。"},{id:"zhou",term:"甃",pinyin:"zhòu",meaning:"用砖石砌护井壁。",context:"「井甃」：修护、稳固井体。小象「修井也」直接点明——修治本身有其正当性。"},{id:"lie",term:"洌",pinyin:"liè",meaning:"清洁、清澈。",context:"「井洌，寒泉食」：不只水清，而且可供饮用——九三「可用汲」却不「食」，到此才把清洁与供饮合起来。"},{id:"shou",term:"收",pinyin:"shōu",meaning:"汲取、汲水之功告成（训释有异，此从一说）。",context:"「井收勿幕」：供养之功已成。注意「收」不是「用完以后收起来」——那是不合本爻的解释。"},{id:"mu",term:"幕",pinyin:"mù",meaning:"覆盖、遮蔽；「勿幕」谓不要封闭、不阻断取用。",context:"「勿幕」重在供养不被遮蔽，不是「防止人掉下去」——后者既无经文依据，也不是合理的安全说明。"},{id:"gangzhong",term:"刚中",pinyin:"gāng zhōng",meaning:"阳爻而居中：九二、九五皆是。",context:"彖传「改邑不改井，乃以刚中也」——「刚中」是井卦稳定供养的结构依据：既有承担与支撑，又不失分寸。"},{id:"fushan",term:"无咎者，善补过也",pinyin:"wú jiù zhě",meaning:"《系辞》语：无咎不只「不好不坏」，而含善于修正、避免过失之意。",context:"但不能把一切「无咎」都读成「先出了错、再补救成功」——六四未明言先有事故，修井也可能是正常维护。"}],r=[{position:"初六",type:"yin",text:"井泥不食，旧井无禽。",xiang:"井泥不食，下也。旧井无禽，时舍也。",textModern:"井底淤泥积聚，水不能饮用；旧井废弃，连禽鸟也不来。初六居全卦最下，阴居阳位不得位，与六四同为阴爻而无正应。小象「下也」指出它处下近井底，「时舍也」则为时所弃、不再被使用。",xiangModern:"井中泥泞不能饮，是因为它处在最下；旧井无禽，是因为已被时势舍弃。"},{position:"九二",type:"yang",text:"井谷射鲋，瓮敝漏。",xiang:"井谷射鲋，无与也。",textModern:"水向下流注，只能润及井中小鱼；汲水的瓮又已破损漏水。九二阳居阴位不得位，但居下卦之中得中，与九五同为阳爻而无正应。小象「无与也」指出缺少相与、接引的条件——水并非全无，却没有形成正常的上汲供养。",xiangModern:"井水只能射及小鱼，是因为没有人来接引取用。"},{position:"九三",type:"yang",text:"井渫不食，为我心恻。可用汲，王明并受其福。",xiang:"井渫不食，行恻也。求王明，受福也。",textModern:"井已淘清淤泥却仍无人饮用，令人惋惜；它已经可以汲取了，只待明察的君王来取用，则上下同受其福。九三阳居阳位得位而不居中，与上六阴阳相应。小象「求王明」点出方向——寻求明察与取用，而不是把「不食」当成理所当然的终局。",xiangModern:"井已淘清却无人饮，令行人惋惜；求明察之人来取用，则共受其福。"},{position:"六四",type:"yin",text:"井甃，无咎。",xiang:"井甃无咎，修井也。",textModern:"用砖石砌护井壁，无咎。六四阴居阴位得位、不居中，与初六无正应，邻近九五。渫是清淤、甃是护壁，两者是不同的修治。小象直接说明「修井也」——在需要修治的时候承担修治，是合宜的行动。",xiangModern:"以砖石修砌井壁而无咎，因为这正是在修治水井。"},{position:"九五",type:"yang",text:"井洌，寒泉食。",xiang:"寒泉之食，中正也。",textModern:"井水清洁，清凉的泉水可供人饮用。九五阳居阳位得位，居上卦之中得中，兼具中与正，通常又称君位——所谓「其正」，应具体落实为「中正」，而非单纯位置高。这里不再是井泥或井渫而不食，而是清洁的水质与供饮作用结合起来了。",xiangModern:"清凉泉水得以供饮，是因为九五中正。"},{position:"上六",type:"yin",text:"井收勿幕，有孚元吉。",xiang:"元吉在上，大成也。",textModern:"汲水之功告成，却不覆盖、不封闭井口，让取用不被阻断；有诚信，大吉。上六阴居阴位得位，与九三阴阳相应，居于全卦之终——但「居终」不能机械理解为衰败，本爻明言「元吉」，应尊重具体经文。小象以「大成」概括。",xiangModern:"大吉在上爻，是因为供养之功大成。"}];return(m,n)=>{const e=t("DaoHexagramViewer"),l=t("DaoHexagramYaoCards"),g=t("DaoKeywordCards");return p(),h("div",null,[i(e,{name:"井",fullName:"水风井",upper:"☵",lower:"☴",guaCi:"井，改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。",pinyin:["jǐng"],element:"木",direction:"东",insight:"井卦讲的不是「井里有水」，而是「水怎么到达人手中」：水质、井体、器具、取用，任一环出问题，供养都不成立。资源的存在不能代替供养的实现，接近完成也不能代替真正完成。",guaSlug:"48shuifengjing",lines:r}),n[0]||(n[0]=o('<h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>巽乎水而上水，井。井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。</p><p>逐句释义：</p><ul><li><strong>巽乎水而上水，井</strong> —— 入于水中，并把水汲取上来。这里不只看见水，也看见了取得水的过程：<strong>井不是静止的「有水」，而包含让水到达人手中的作用。</strong></li><li><strong>井养而不穷也</strong> —— 井的义理在于持续供养，不是一次性的占有或消耗。但「养而不穷」不等于不用治理、无须工具、不会失败、可以无条件索取——它是井所体现的<strong>供养之道</strong>，不是对每一口具体水井状态的保证。</li><li><strong>改邑不改井，乃以刚中也</strong> —— 九二、九五都是阳爻而居中。「刚中」是井卦稳定供养的结构依据；借到为人处世上，可体会为<strong>既有承担与支撑，又不失分寸</strong>（但不能简化成「只要性格刚强，就一定能养人」）。</li><li><strong>汔至亦未繘井，未有功也</strong> —— 这里的「功」不是付出了多少努力，而是<strong>汲取之功是否完成</strong>。</li><li><strong>羸其瓶，是以凶也</strong> —— 已近成功而瓶损，故凶。</li></ul><blockquote><p><strong>「未有功也」是井卦最重要的实践提醒</strong>：做了很多、已经接近成功，都不等于人已经得到水。既要尊重过程，也要检验实际结果。</p></blockquote><h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>木上有水，井。君子以劳民劝相。</p><p>从木与水的关系取井象，与彖传「上水」相呼应。</p><p><strong>「劳民劝相」</strong>：「劳民」通常从慰劳、勤恤民众方面解释，「劝相」是劝勉相助。因而不能把这句话直接读成「为了公共利益，就可以无限度地使民劳作」。更合适的体会是：君子由井的供养之象，想到照顾民众，并促成彼此协作。</p><blockquote><p><strong>从「井的供养」转向「人的治理」。</strong> 如果井是共同使用的资源，那么治理不仅涉及设施，还涉及人：谁负责维护、谁承担劳动、谁可以取用、人们怎样相助。但经文并没有直接规定一套现代公共管理制度——具体制度分析，需要另有事实与论证。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',11)),i(l,{element:"木",guaSlug:"48shuifengjing",glossary:a,items:r}),n[1]||(n[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><p>贯穿全卦的一条区别是：<strong>井里有水，不等于人已经得到滋养。</strong> 中间还隔着水质、井体、器具、取用与供养的通畅。六爻正好把这几种处境分开来写：井泥（初六）、瓮漏（九二）、可用而未用（九三）、修治（六四）、清泉供饮（九五）、大成而不封闭（上六）。</p><p>卦辞先立规范：城邑可改而井不改，井没有简单的得失，往来之人都来取水；然而「汔至亦未繘井，羸其瓶」，<strong>已近完成而失手，仍然是凶</strong>。</p><h3 id="初六-·-井泥不食-旧井无禽" tabindex="-1">初六 · 井泥不食，旧井无禽 <a class="header-anchor" href="#初六-·-井泥不食-旧井无禽" aria-label="Permalink to &quot;初六 · 井泥不食，旧井无禽&quot;">​</a></h3><ul><li><strong>井泥不食</strong>：井底淤泥积聚，水不能饮用；<strong>旧井无禽</strong>：旧井废弃，连禽鸟也不来</li><li>初六居最下、阴居阳位不得位、与六四同为阴而无正应；小象「<strong>下也</strong>」「<strong>时舍也</strong>」</li></ul><p>这一爻是全卦的「先看见实际失效」。<strong>不能因为它叫「井」，就认定它现在能养人。</strong></p><blockquote><p>过去有用、名称美好、原本具有价值，都不能代替眼下的可用性。</p></blockquote><p><strong>现实映照</strong>：技能可能过时，系统可能失修，组织也可能失去服务能力。这些是帮助理解的类比，不是说经文已经直接讨论现代组织。</p><h3 id="九二-·-井谷射鲋-瓮敝漏" tabindex="-1">九二 · 井谷射鲋，瓮敝漏 <a class="header-anchor" href="#九二-·-井谷射鲋-瓮敝漏" aria-label="Permalink to &quot;九二 · 井谷射鲋，瓮敝漏&quot;">​</a></h3><ul><li><strong>井谷射鲋</strong>：训释有差异，此取水向下流注、只能润及井中小鱼一路；<strong>瓮敝漏</strong>：汲水的瓮已经破损漏水</li><li>九二阳居阴位不得位、居下卦之中得中、与九五同为阳而无正应；小象「<strong>无与也</strong>」</li></ul><p><strong>源头有资源，不等于资源能够到达使用者。</strong> 取用的方向、通道和器具，都可能成为阻碍。</p><p><strong>辨析</strong>：不能把「瓮敝漏」硬解释成「九二太刚，所以刚则易折」。经文写出了破漏状态，却没有给出这条性格因果链——<strong>联想不能冒充证据</strong>。</p><h3 id="九三-·-井渫不食-为我心恻-可用汲-王明并受其福" tabindex="-1">九三 · 井渫不食，为我心恻；可用汲，王明并受其福 <a class="header-anchor" href="#九三-·-井渫不食-为我心恻-可用汲-王明并受其福" aria-label="Permalink to &quot;九三 · 井渫不食，为我心恻；可用汲，王明并受其福&quot;">​</a></h3><ul><li><strong>渫</strong>：清除井中淤泥；<strong>不食</strong>：没有被饮用；<strong>心恻</strong>：为此惋惜；<strong>可用汲</strong>：已经可以汲取；<strong>王明</strong>：期望明察者识别、任用；<strong>并受其福</strong>：共同受到其益</li><li>九三阳居阳位得位而不居中、与上六阴阳相应；小象强调「<strong>求王明</strong>」</li></ul><p><strong>修好自己，不等于已经实现供养；可用之物，也可能没有被识别、没有进入实际使用。</strong></p><blockquote><p>这里确实存在惋惜，但不能由此得出：人只能被动等待认可；任何未被任用者都必然有才；只要被权威发现，就一定能造福众人。</p></blockquote><p><strong>「我」字的处理</strong>：「为我心恻」中的「我」如何理解，可结合注家讨论，不必直接认定是作者本人在表达感受。</p><h3 id="六四-·-井甃-无咎" tabindex="-1">六四 · 井甃，无咎 <a class="header-anchor" href="#六四-·-井甃-无咎" aria-label="Permalink to &quot;六四 · 井甃，无咎&quot;">​</a></h3><ul><li><strong>甃</strong>：用砖石砌护井壁</li><li><strong>渫与甃的分工</strong>：渫是清除井内淤泥，甃是修护稳固井体；甃不直接修汲水的绳、瓶或瓮</li><li>六四阴居阴位得位、不居中、与初六无正应、邻近九五；小象直接说明「<strong>修井也</strong>」</li></ul><p><strong>在需要修治的时候承担修治，是合宜的行动。</strong></p><p><strong>「无咎」的分寸</strong>：《系辞》说「无咎者，善补过也」——无咎不是模糊的「不好不坏」，而包含善于修正、避免过失的意义。但也不能把所有「无咎」一律读成「已经出错、然后补救成功」：六四并未明言先发生事故，修井也可能是正常维护。同样，无咎不等于大吉，也不等于经文已经交代供养完成。</p><h3 id="九五-·-井洌-寒泉食" tabindex="-1">九五 · 井洌，寒泉食 <a class="header-anchor" href="#九五-·-井洌-寒泉食" aria-label="Permalink to &quot;九五 · 井洌，寒泉食&quot;">​</a></h3><ul><li><strong>洌</strong>：清洁、清澈；<strong>寒泉</strong>：清凉的泉水；<strong>食</strong>：供人饮用</li><li>九五阳居阳位得位、居上卦之中得中，兼具中与正，通常又称君位</li></ul><p>所谓九五「其正」，应具体落实为「<strong>中正</strong>」，而非单纯位置高。</p><blockquote><p>这里不再是井泥或井渫而不食，而是<strong>清洁泉水与供饮作用相结合</strong>。</p></blockquote><p><strong>与九三的分辨</strong>：「洌」很重要，但更要看「食」——九三已「可用汲」却不「食」，九五才把清泉与供饮合起来。</p><p><strong>辨析</strong>：不能认定九五一定是初六至六四全部工序完成后的结果，也不能认定经文已经叙述「君王明察之后井才被使用」，更不能说「只要本质清澈，就必然自然得到使用」。九五有君位象征，可与九三「王明」相互参照，但这些不等于经文给出了一条确定的事件因果链。</p><h3 id="上六-·-井收勿幕-有孚元吉" tabindex="-1">上六 · 井收勿幕，有孚元吉 <a class="header-anchor" href="#上六-·-井收勿幕-有孚元吉" aria-label="Permalink to &quot;上六 · 井收勿幕，有孚元吉&quot;">​</a></h3><ul><li><strong>收</strong>：训释有异，此取「汲取、汲水之功告成」；<strong>勿幕</strong>：不要覆盖、封闭，重在不阻断取用；<strong>有孚</strong>：有诚信、可信实；<strong>元吉</strong>：大吉</li><li>上六阴居阴位得位、与九三阴阳相应、居全卦之终；小象以「<strong>大成</strong>」概括</li></ul><p><strong>供养之功已成，却不将供养封闭起来。</strong> 它不只是一次取到水，也指向让人仍能取用、仍可依靠的状态。</p><p><strong>两处必须纠正的旧说</strong>：① 把「收」说成「用完以后收敛、收起来」——不合本爻，不宜再作依据；② 把「不盖井」解释成「防止人掉下去」——既缺乏经文依据，也不是合理的安全说明。「勿幕」重在供养不被遮蔽、封闭；现实中的井口安全措施应另行处理。</p><p><strong>关于「有孚」的联想边界</strong>：诚信、爱护共同资源、避免污染浪费，是有价值的现实映照；但井卦上六说「有孚」，<strong>不等于直接援引了中孚卦的全部义理</strong>——感恩、环保、共治等具体伦理，需要另作展开。</p><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',33)),i(g,{title:"字词释义",items:[{term:"井",pinyin:["jǐng"],meaning:"水井。卦中既指具体的井，也指「供养之道」——关键不在井里有水，而在水如何到达人手中。"},{term:"改邑不改井",pinyin:["gǎi","yì"],meaning:"城邑可以迁改，井的所在与供养功能相对固定。彖传以「刚中」释之：稳定供养的结构依据。"},{term:"无丧无得",pinyin:["wú","sàng"],meaning:"从井的常养之性看，不随人的往来而有简单的得失变化。但不是说井水物理上永不减少，也不是说具体水井无需维护。"},{term:"往来井井",pinyin:["wǎng","lái"],meaning:"往来的人都到井边取水。写井的常养之性——人来人往，供养的需要始终存在。"},{term:"汔至亦未繘井",pinyin:["qì","zhì"],meaning:"汲水几乎到井口了，却终究没有把水取上来。「繘」为汲水绳，训释各家有异。彖传「未有功也」即释此句。"},{term:"羸其瓶",pinyin:["léi","qí","píng"],meaning:"汲水的瓶受牵累、损伤，以致汲水失败——已近成功，却因最后一环失手，故凶。"},{term:"巽乎水而上水",pinyin:["xùn","hū"],meaning:"入于水中并把水汲取上来。彖传释井：不只看见水，也看见取得水的过程。"},{term:"井养而不穷",pinyin:["jǐng","yǎng"],meaning:"井的义理在于持续供养，而非一次性的占有或消耗。它是供养之道，不是对每一口具体水井状态的保证。"},{term:"劳民劝相",pinyin:["láo","mín"],meaning:"慰劳、勤恤民众，劝勉相助。不能读成「为了公共利益就可以无限度使民劳作」。"},{term:"井泥不食",pinyin:["jǐng","ní"],meaning:"井底淤泥积聚，水不能饮用。象曰「下也」——与其处下、近井底的状态有关。"},{term:"旧井无禽",pinyin:["jiù","jǐng"],meaning:"旧井废弃，连禽鸟也不来。象曰「时舍也」——为时所弃，不再被使用。重点在失去吸引取用者的作用。"},{term:"井谷射鲋",pinyin:["jǐng","gǔ"],meaning:"训释有差异，此取水向下流注、只能润及井中小鱼一路。象曰「无与也」——缺少相与、接引的条件。"},{term:"瓮敝漏",pinyin:["wèng","bì","lòu"],meaning:"汲水的瓮已破损漏水。水并非全无，却没有形成正常的上汲供养，器具又不能承载。"},{term:"渫",pinyin:["xiè"],meaning:"清除井中的淤泥。与「甃」分工不同：渫清淤（九三），甃护壁（六四）。"},{term:"为我心恻",pinyin:["wèi","wǒ"],meaning:"为此感到惋惜。「我」如何理解，可结合注家讨论，不必直接认定是作者自述。"},{term:"王明",pinyin:["wáng","míng"],meaning:"期望明察者识别、任用。象曰「求王明，受福也」——寻求明察与取用，而非把「不食」当作理所当然的终局。"},{term:"甃",pinyin:["zhòu"],meaning:"用砖石砌护井壁。象曰「修井也」——在需要修治的时候承担修治，是合宜的行动。"},{term:"井洌，寒泉食",pinyin:["liè","hán","quán"],meaning:"井水清洁，清凉的泉水可供人饮用。象曰「中正也」——九五「其正」应落实为「中正」，而非单纯位置高。"},{term:"井收勿幕",pinyin:["shōu","wù","mù"],meaning:"汲水之功告成，却不覆盖、不封闭井口，让取用不被阻断。「收」非「用完收起来」；「勿幕」非「防止人掉下去」。"},{term:"有孚",pinyin:["yǒu","fú"],meaning:"有诚信、可信实；结合井的情境，也可体会其供养具有可信赖性。不等于援引中孚卦的全部义理。"}]}),n[2]||(n[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>水风井：上坎为水（亦有险义），下巽为风、为木（亦有入、顺入义）。彖传以「巽乎水而上水」解释井象，大象以「木上有水」取象——学习时可以从木制汲水器具入水、将水取上的形象体会，不必把卦象硬当作一幅现代机械图。</p><p>贯穿全卦的一条区别是：</p><blockquote><p><strong>井里有水，不等于人已经得到滋养。</strong></p></blockquote><p>中间还涉及：水是否清洁、井体是否稳固、汲取器具是否可用、可用之水是否被取用、供养能否保持通畅。井卦因此不只是赞美资源，也让我们看见<strong>资源失效、修治、未被取用与供养实现</strong>的不同处境。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>井卦把「供给」这件事拆成了必须逐项检验的几个环节：</p><ol><li><strong>资源的存在，不能代替供养的实现</strong>——初六井泥、九二瓮漏，写的都是有水却养不成人。</li><li><strong>接近完成，也不能代替真正完成</strong>——卦辞「汔至亦未繘井，羸其瓶，凶」，彖传一句「未有功也」点得很准：功不是付出了多少努力，是汲取之功有没有完成。</li><li><strong>可用 ≠ 被用</strong>——九三已「可用汲」却「不食」。修好自己与实现供养之间，还有一段距离。</li><li><strong>修治本身有其正当性</strong>——六四「井甃，无咎」，不必等出了大事才承认维护的价值。</li><li><strong>大成在于不封闭</strong>——上六「井收勿幕」，供养之功告成，却不让它被遮蔽、被独占。</li></ol><p>而这一切的结构依据是「刚中」：九二、九五都是阳爻居中——<strong>既有承担与支撑，又不失分寸。</strong></p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ul><li><strong>先分清是哪一环出了问题</strong>：是水质（内容本身不行）？井体（基础设施失修）？器具（交付手段坏了）？还是取用（没人来取）？</li><li><strong>别把「快好了」当成「好了」</strong>：临近交付时的失手，代价往往最大。井卦把它直接判为「凶」。</li><li><strong>可用不等于被用</strong>：手上有一套能用的东西，先问它有没有真的进入别人的使用。</li><li><strong>维护要有人承担</strong>：清淤、护壁、器具维护，这些不被看见的劳动，是供养能持续的前提。</li><li><strong>成了之后不要封井</strong>：成果出来了，还要保持取用通畅、可信——不遮蔽、不独占。</li></ul><h2 id="【解读层】核心框架" tabindex="-1">【解读层】核心框架 <a class="header-anchor" href="#【解读层】核心框架" aria-label="Permalink to &quot;【解读层】核心框架&quot;">​</a></h2><p>以下三组框架可复用于其他卦，也可直接用于读工程、读治理。</p><h3 id="_1-有水-得养-供养的四重条件" tabindex="-1">1. 有水 ≠ 得养：供养的四重条件 <a class="header-anchor" href="#_1-有水-得养-供养的四重条件" aria-label="Permalink to &quot;1. 有水 ≠ 得养：供养的四重条件&quot;">​</a></h3><p>井卦提供了一套可逐项检查的清单：</p><table tabindex="0"><thead><tr><th>环节</th><th>失守时会怎样</th><th>对应爻</th></tr></thead><tbody><tr><td>水质</td><td>水在，但不可饮</td><td>初六（井泥）</td></tr><tr><td>通道 / 器具</td><td>水在，但上不来、盛不住</td><td>九二（瓮敝漏）</td></tr><tr><td>取用</td><td>水已可用，但无人取</td><td>九三（渫不食）</td></tr><tr><td>维护</td><td>条件尚可，但无人修治</td><td>六四（井甃）</td></tr></tbody></table><p>再加一条正向的判据：<strong>供养是否保持通畅、不封闭</strong>（上六「勿幕」）。</p><blockquote><p>判断任何「供给」是否成立，只需顺着这四环走一遍——<strong>资源存在只是第一环。</strong></p></blockquote><h3 id="_2-可用-被用" tabindex="-1">2. 可用 ≠ 被用 <a class="header-anchor" href="#_2-可用-被用" aria-label="Permalink to &quot;2. 可用 ≠ 被用&quot;">​</a></h3><p>九三是全卦最能用来反思的一组处境：井已淘清（可用了），却「不食」（没人用）。但井卦同时给出了边界——</p><ul><li>惋惜是真的（「为我心恻」）；</li><li>但不能推出「人只能被动等待认可」；</li><li>也不能推出「凡未被任用者都必然有才」；</li><li>更不能推出「只要被权威发现，就一定能造福众人」。</li></ul><p><strong>「求王明」是方向，不是保证。</strong></p><h3 id="_3-六爻是六种观察角度-不是六项必经工序" tabindex="-1">3. 六爻是六种观察角度，不是六项必经工序 <a class="header-anchor" href="#_3-六爻是六种观察角度-不是六项必经工序" aria-label="Permalink to &quot;3. 六爻是六种观察角度，不是六项必经工序&quot;">​</a></h3><p>这是读井卦最容易出错的地方。表里六爻各写一种状态，但它不是同一口井从坏到好的施工顺序：</p><ul><li>初六、九二不是说「什么都没做」，而是<strong>经文没有记述相应的修治行为</strong>；</li><li>六四也没有明言「绝对无人饮水」，只是<strong>不以「食」作为本爻着眼点</strong>；</li><li>九三已明说「可用汲」，所以<strong>不能因为六四仍在修井，就倒推九三「其实还不能用」</strong>——渫与甃是不同修治，六爻是不同处境。</li></ul><h3 id="附-三种需要警惕的读法" tabindex="-1">附：三种需要警惕的读法 <a class="header-anchor" href="#附-三种需要警惕的读法" aria-label="Permalink to &quot;附：三种需要警惕的读法&quot;">​</a></h3><ol><li><strong>故事化</strong>——为了让解释顺畅，替经文补上未经支持的心理与因果。</li><li><strong>流程化</strong>——把六爻强行排成同一事件必须完成的六个阶段。</li><li><strong>结果倒推</strong>——因为最后「元吉」，就认为前面的风险必然值得、失效必然有益。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><h3 id="从「井的美好」-转向「井的处境」" tabindex="-1">从「井的美好」，转向「井的处境」 <a class="header-anchor" href="#从「井的美好」-转向「井的处境」" aria-label="Permalink to &quot;从「井的美好」，转向「井的处境」&quot;">​</a></h3><p>学习之前，想到井，容易只想到清水与滋养。学习之后，才看见：</p><ul><li>井可能有泥；</li><li>瓮可能破漏；</li><li>水可能可用却未被用；</li><li>井体仍须修护。</li></ul><p><strong>名称、理想与过去的价值，不能代替实际条件。</strong></p><h3 id="从「有价值」-转向「价值怎样到达人」" tabindex="-1">从「有价值」，转向「价值怎样到达人」 <a class="header-anchor" href="#从「有价值」-转向「价值怎样到达人」" aria-label="Permalink to &quot;从「有价值」，转向「价值怎样到达人」&quot;">​</a></h3><p>水在井中，只是起点。对个人、团队或项目而言，也不能只问「我有没有能力」「我们有没有资源」，还要问：</p><blockquote><p><strong>能力和资源，有没有转化为别人实际得到的帮助？</strong></p></blockquote><p>但这不意味着人的全部价值只能由外部认可决定——这里讨论的是供养、服务等作用的实现，而不是人的尊严与全部意义。</p><h3 id="从「一次成功」-转向「持续照料」" tabindex="-1">从「一次成功」，转向「持续照料」 <a class="header-anchor" href="#从「一次成功」-转向「持续照料」" aria-label="Permalink to &quot;从「一次成功」，转向「持续照料」&quot;">​</a></h3><p>一杯可饮的水，看起来日常，背后可能有清淤、护壁、器具维护与许多不被看见的劳动。</p><blockquote><p>结果的美好，会让我们忘记初始和环境的艰难。</p></blockquote><p>进一步说，已经可用的成果，也不应让我们忘记维持它的条件。</p><h3 id="从「个人修治」-转向「共同供养」" tabindex="-1">从「个人修治」，转向「共同供养」 <a class="header-anchor" href="#从「个人修治」-转向「共同供养」" aria-label="Permalink to &quot;从「个人修治」，转向「共同供养」&quot;">​</a></h3><p>井卦可以帮助我们思考：自身是否可用、取用是否通畅、价值是否被识别、维护是否有人承担、供养是否被封闭。</p><blockquote><p>这是一种现实治理的映照，而不是说井卦已经预先写出了现代制度。</p></blockquote><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>读井卦，最先被改掉的念头是：<strong>以前想到井，只想到清水。</strong> 现在会先问一句——这口井现在是什么状态？井泥？瓮漏？还是淘清了却没人来取？</p><p>第二处让我停下来的是「未有功也」这四个字。彖传解释卦辞，没有说「你没努力」，说的是<strong>汲取之功没有完成</strong>。这一句拿来检视手上的事很利：做了很多、已经接近成功，都不等于有人真的拿到了水。</p><p>第三处是六四。这是全卦最不显眼的一爻——没有吉，也没有凶，只说「井甃，无咎」。但它承认了一件事：<strong>修治本身就有正当性</strong>，不必等出了大事、也不必等它换来什么结果。</p><p>第四处是上六的「勿幕」。供养做成了，却不把井盖起来——<strong>大成不是占有，是仍然让水能被取到。</strong></p><p>另外记下两条读法上的自我提醒：</p><ul><li><strong>不要把六爻读成施工顺序</strong>。九三已经「可用汲」了，不能因为六四还在修井，就倒推九三还不能用。渫与甃是两种修治，六爻是六种处境。</li><li><strong>联想不能冒充证据</strong>。「瓮敝漏」不能推出「九二太刚所以易折」；「收」不是「用完收起来」；「勿幕」也不是「防止人掉下去」。这些说法听起来顺，但经文没写。</li></ul><p>最后留下一处想接着走：</p><ul><li><strong>井与困</strong>：序卦说「困乎上者必反下，故受之以井」——困是穷于上，井是养于下；两卦相接，正好是一断一续，值得并读一次。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：<a href="/Dao/yijing/hexagrams/47-zeshukun">困（第四十七卦）</a>、<a href="/Dao/yijing/hexagrams/57-xunweifeng">巽（第五十七卦）</a>、<a href="/Dao/yijing/hexagrams/29-kanweishui">坎（第二十九卦）</a>、<a href="/Dao/yijing/hexagrams/60-shuizejie">节（第六十卦）</a></li><li>井与困：序卦相连——「困乎上者必反下，故受之以井」。困是穷于上，井是养于下</li><li>井与巽、坎：下巽为木、上坎为水，「巽乎水而上水」；大象「木上有水」同此取象。巽之「入」、坎之「险」也进入了井的处境</li><li>井与节：讲的都是「限度」。井讲供养不被封闭（勿幕），节讲取用应有尺度（制度）——一端是「不可挡住」，一端是「不可无度」</li></ul>',55))])}}});export{x as __pageData,q as default};
